typedef struct {
    int8_t intr, tabl, ofs1, ofs2, drft, phas, ntyp, nlev, ncut, ndec;
    int8_t fres, fnotc, fnotk, ftype; /* the filter: RES, 127 - CUT, 127 - KEY, TYPE (zeros: no filter, 100 % key, LP) */
} wvt_x_t;
