/* the preset a track just loaded (ui.c apply_preset_to, tests/hostsim.c): its operator slots (the common part of a sound
 * load has set them to TP's defaults) */
static void wvt_track_loaded(track_t *t)
{
    const wvt_x_t *x;
    if (t->eng_req != 16u)
        return;
    x = &WVT_X[(uint32_t)t->preset % (sizeof(WVT_X) / sizeof((WVT_X)[0]))];
    t->p[P_FM1_ATK] = x->intr;
    t->p[P_FM1_DEC] = x->tabl;
    t->p[P_FM1_REL] = x->ofs1;
    t->p[P_FM2_REL] = x->ofs2;
    t->p[P_FM2_ATK] = x->drft;
    t->p[P_FM2_DEC] = x->phas;
    t->p[P_FM3_ATK] = x->ntyp;
    t->p[P_FM3_DEC] = x->nlev;
    t->p[P_FM1_SUS] = x->ncut;
    t->p[P_FM2_SUS] = x->ndec;
    t->p[P_FM3_REL] = x->fres;
    t->p[P_FM3_SUS] = 127 - x->fnotc;
    t->p[P_FM3_LEVEL] = 127 - x->fnotk;
    t->p[P_FTYPE] = x->ftype;
}
