    int32_t gfold = 256 + fold * 14, tg = trlv * 258, vg = (int32_t)v->vel * 258, dx1, dy1, fb1, fb2;
    uint32_t inc[3], inc1[3], dinc[3], ph[3], ra = fdr_ratio(p[P_FM1_ATK]), rb = fdr_ratio(p[P_FM1_DEC]), rc = fdr_ratio(p[P_FM1_REL]), base;
