/* the preset a track just loaded (ui.c apply_preset_to, tests/hostsim.c): its slots */
static void fdr_track_loaded(track_t *t)
{
    const fdr_x_t *x;
    if (t->eng_req != 17u)
        return;
    x = &FDR_X[(uint32_t)t->preset % (sizeof(FDR_X) / sizeof((FDR_X)[0]))];
    t->p[P_FM1_ATK] = x->rta;
    t->p[P_FM1_DEC] = x->rtb;
    t->p[P_FM1_REL] = x->rtc;
    t->p[P_FM2_ATK] = x->mac;
    t->p[P_FM2_DEC] = x->mba;
    t->p[P_FM2_REL] = x->mbc;
    t->p[P_FM3_ATK] = x->hold;
    t->p[P_FM3_DEC] = x->decy;
    t->p[P_FM3_REL] = x->envr;
    t->p[P_FM4_ATK] = x->trlv;
    t->p[P_FM4_DEC] = x->trsl;
    t->p[P_FM4_REL] = x->nlev;
    t->p[P_FM1_SUS] = x->phsc;
    t->p[P_FM1_LEVEL] = x->trlp;
    t->p[P_FM2_SUS] = x->ndcy;
    t->p[P_FM2_LEVEL] = x->ncol;
}
