/* the preset a track just loaded (ui.c apply_preset_to, tests/hostsim.c): its filter */
static void chip_track_loaded(track_t *t)
{
    const int8_t *x;
    if (t->eng_req != 19u)
        return;
    x = CHP_X[(uint32_t)t->preset % (sizeof(CHP_X) / sizeof((CHP_X)[0]))];
    t->p[P_FM1_REL] = x[0];
    t->p[P_FM1_SUS] = 127 - x[1];
    t->p[P_FM1_LEVEL] = 127 - x[2];
    t->p[P_FTYPE] = x[3];
}
