    case MACRO_OSC_SHAPE_TRIPLE_TRIANGLE: base_shape = OSC_SHAPE_TRIANGLE; break;
    case MACRO_OSC_SHAPE_TRIPLE_SQUARE: base_shape = OSC_SHAPE_SQUARE; break;
