/* the preset a track just loaded (ui.c apply_preset_to, tests/hostsim.c): the voices' levels */
static void t8_track_loaded(track_t *t)
{
    uint32_t i;
    if (t->eng_req != 24u)
        return;
    for (i = 0; i < 16; i++)
        t->p[P_FM1_ATK + i] = T8_LEVELS[(uint32_t)t->preset % (sizeof(T8_PRESETS) / sizeof((T8_PRESETS)[0]))][i];
}
