        if ((0x69u >> k) & 1u) {
            for (s = 0; s < (32 / 2u); s += m) { m = (HL_LEN[k]) - (d) < (32 / 2u) - s ? (HL_LEN[k]) - (d) : (32 / 2u) - s; hall_end_lp(b + d, PKV(44).y[k] + s, m, g, lo, &PKV(44).lp[k], &PKV(44).le[k], kd); d = (d) + m >= (HL_LEN[k]) ? 0u : (d) + m; };
        } else {
            for (s = 0; s < (32 / 2u); s += m) { m = (HL_LEN[k]) - (d) < (32 / 2u) - s ? (HL_LEN[k]) - (d) : (32 / 2u) - s; hall_end(b + d, f, PKV(44).y[k] + s, m, g, lo); d = (d) + m >= (HL_LEN[k]) ? 0u : (d) + m; };
        }
