        int32_t y0 = PKV(44).y[0][i], y1 = PKV(44).y[1][i], y2 = PKV(44).y[2][i], y3 = PKV(44).y[3][i];
        int32_t y4 = PKV(44).y[4][i], y5 = PKV(44).y[5][i], y6 = PKV(44).y[6][i], y7 = PKV(44).y[7][i], x = PKV(44).bx[i];
