        PKV(44).y[3][i] = (int16_t)clamp(2 * p2 + y3 - y0 + x, -32768, 32767);
        PKV(44).y[4][i] = (int16_t)clamp(2 * p3 + y4 - y0 + x, -32768, 32767);
