        b0 = a0 + a2, b1 = a1 + a3, b2 = a0 - a2, b3 = a1 - a3;
        b4 = a4 + a6, b5 = a5 + a7, b6 = a4 - a6, b7 = a5 - a7;
        f[0] = b0 + b4, f[1] = b1 + b5, f[2] = b2 + b6, f[3] = b3 + b7;
        f[4] = b0 - b4, f[5] = b1 - b5, f[6] = b2 - b6, f[7] = b3 - b7;
